package com.dixitdada.journalApp.service; import com.dixitdada.journalApp.entity.User; import com.dixitdada.journalApp.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService { private final UserRepository users; public UserDetails loadUserByUsername(String n){ User u=users.findByUsername(n).orElseThrow(()->new UsernameNotFoundException(n)); return new org.springframework.security.core.userdetails.User(u.getUsername(),u.getPassword(),u.getRoles().stream().map(r->new SimpleGrantedAuthority("ROLE_"+r)).toList()); } }